import React, { useState } from 'react';
import { getProductImage } from '../data/menuData';

const weightLabels = { "1KG": "1 KG", "1/2KG": "½ KG", "250GM": "250 GM" };

function ProductCard({ product, onAddToCart }) {
  const [selectedWeight, setSelectedWeight] = useState("1KG");
  const [isHovered, setIsHovered] = useState(false);
  const [added, setAdded] = useState(false);
  const [imgError, setImgError] = useState(false);

  const handleAdd = () => {
    onAddToCart(product, selectedWeight);
    setAdded(true);
    setTimeout(() => setAdded(false), 1200);
  };

  return (
    <div
      className={`group bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-500 ease-out ${isHovered ? 'scale-[1.03] -translate-y-2' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Image with gradient overlay */}
      <div className="relative h-48 overflow-hidden bg-gradient-to-br from-orange-100 to-amber-100">
        {!imgError ? (
          <img
            src={getProductImage(product)}
            alt={product.name}
            className={`w-full h-full object-cover transition-all duration-700 ${isHovered ? 'scale-110' : 'scale-100'}`}
            loading="lazy"
            onError={() => setImgError(true)}
          />
        ) : (
          <div className={`w-full h-full bg-gradient-to-br ${product.bgColor || 'from-orange-100 to-amber-100'} flex items-center justify-center`}>
            <span className="text-6xl opacity-40">{product.emoji || '🍽️'}</span>
          </div>
        )}
        <div className={`absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent transition-opacity duration-300 ${isHovered ? 'opacity-100' : 'opacity-60'}`}></div>
        <span className="absolute top-3 left-3 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-semibold text-gray-700 shadow-lg">
          {product.category}
        </span>
        {!product.in_stock && (
          <span className="absolute top-3 right-3 bg-red-500 text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg animate-pulse">
            Out of Stock
          </span>
        )}
      </div>

      {/* Content */}
      <div className="p-4">
        <h3 className="text-lg font-bold text-gray-800 mb-3 group-hover:text-[var(--maroon)] transition-colors">{product.name}</h3>

        {/* Weight Selector - All 3 tiers */}
        <div className="flex gap-1.5 mb-3">
          {Object.entries(product.prices).map(([weight, price]) => (
            <button
              key={weight}
              onClick={() => setSelectedWeight(weight)}
              className={`flex-1 py-2 px-1 rounded-lg text-xs font-semibold transition-all duration-200 ${
                selectedWeight === weight
                  ? 'bg-gradient-to-r from-[var(--maroon)] to-[var(--saffron)] text-white shadow-lg scale-105'
                  : 'bg-gray-100 text-gray-600 hover:bg-[var(--saffron-light)] hover:text-white'
              }`}
            >
              <div>{weightLabels[weight]}</div>
              <div className="mt-0.5">₹{price}</div>
            </button>
          ))}
        </div>

        {/* Highlighted selected price */}
        <div className="flex items-center justify-between mb-3 bg-gradient-to-r from-[var(--saffron-light)]/20 to-[var(--cream)] rounded-lg px-3 py-2 border border-[var(--gold-light)]/30">
          <span className="text-sm text-gray-600 font-medium">{weightLabels[selectedWeight]}</span>
          <div className="flex items-center gap-2">
            <span className="text-xs text-gray-400 line-through">₹{product.prices[selectedWeight] + Math.round(product.prices[selectedWeight] * 0.1)}</span>
            <span className="text-xl font-bold text-[var(--maroon)]">₹{product.prices[selectedWeight]}</span>
          </div>
        </div>

        {/* Add to Cart */}
        <button
          onClick={handleAdd}
          disabled={added || !product.in_stock}
          className={`w-full py-3 rounded-xl font-bold text-sm transition-all duration-300 ${
            added
              ? 'bg-green-500 text-white scale-105'
              : !product.in_stock
                ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                : isHovered
                  ? 'bg-gradient-to-r from-[var(--maroon)] to-[var(--saffron)] text-white shadow-lg shadow-[var(--maroon)]/30'
                  : 'bg-gray-100 text-gray-700 hover:bg-[var(--maroon)] hover:text-white'
          }`}
        >
          <span className="flex items-center justify-center gap-2">
            {added ? '✅ Added!' : !product.in_stock ? '❌ Unavailable' : '🛒 Add to Cart'}
            {isHovered && !added && product.in_stock && <span className="inline-block animate-bounce">→</span>}
          </span>
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
